input.command:
mkdir -p /tmp/claude-0/-tmp-eff-qldt-wx8-work/a4eb1cb7-866c-5bbf-8d81-a8d5acd83be3/scratchpad && cd $_ 2>/dev/null; SP=/tmp/claude-0/-tmp-eff-qldt-wx8-work/a4eb1cb7-866c-5bbf-8d81-a8d5acd83be3/scratchpad; cat > $SP/dashboard.json <<'EOF'
{
  "title": "EFF-1846a502 Web logs overview",
  "description": "Key traffic and error metrics from the Kibana sample web logs.",
  "time_range": { "from": "now-7d", "to": "now" },
  "panels": [
    {
      "grid": { "x": 0, "y": 0, "w": 16, "h": 6 },
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Total requests",
        "data_source": {
          "type": "esql",
          "query": "FROM kibana_sample_data_logs | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend | STATS requests = COUNT()"
        },
        "metrics": [ { "type": "primary", "column": "requests" } ]
      }
    },
    {
      "grid": { "x": 16, "y": 0, "w": 16, "h": 6 },
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "5xx responses",
        "data_source": {
          "type": "esql",
          "query": "FROM kibana_sample_data_logs | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend AND response.keyword LIKE \"5*\" | STATS errors = COUNT()"
        },
        "metrics": [ { "type": "primary", "column": "errors" } ]
      }
    },
    {
      "grid": { "x": 32, "y": 0, "w": 16, "h": 6 },
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Average response size (bytes)",
        "data_source": {
          "type": "esql",
          "query": "FROM kibana_sample_data_logs | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend | STATS avg_bytes = AVG(bytes)"
        },
        "metrics": [ { "type": "primary", "column": "avg_bytes" } ]
      }
    },
    {
      "grid": { "x": 0, "y": 6, "w": 48, "h": 12 },
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Requests over time by response code",
        "layers": [
          {
            "type": "bar",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend), response.keyword"
            },
            "x": { "column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)" },
            "y": [ { "column": "count" } ],
            "breakdown": { "column": "response.keyword" }
          }
        ],
        "axis": { "x": { "title": { "visible": false } } }
      }
    },
    {
      "grid": { "x": 0, "y": 18, "w": 24, "h": 12 },
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Requests by response code",
        "layers": [
          {
            "type": "bar",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend | STATS requests = COUNT() BY response.keyword | SORT requests DESC | LIMIT 10"
            },
            "x": { "column": "response.keyword" },
            "y": [ { "column": "requests" } ]
          }
        ]
      }
    },
    {
      "grid": { "x": 24, "y": 18, "w": 24, "h": 12 },
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Top 10 URLs by requests",
        "layers": [
          {
            "type": "bar",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend | STATS requests = COUNT() BY url.keyword | SORT requests DESC | LIMIT 10"
            },
            "x": { "column": "url.keyword" },
            "y": [ { "column": "requests" } ]
          }
        ]
      }
    }
  ]
}
EOF
curl -sS -X POST -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json" "$KIBANA_URL/api/dashboards" -d @$SP/dashboard.json | head -c 1500

